const verifServiceList = `-- name: VerifServiceList :many

SELECT v.id, v.workspace_id, v.service, v.region, v.credentials_enc, v.price_micros, v.default_bulk, v.default_forms, v.balance, v.balance_at, v.last_used_at, v.last_used_by, v.last_used_what, v.last_error, v.last_error_at, v.last_error_since, v.last_success_at, v.last_success_what, v.tested_at, v.test_ok, v.low_notified_at, v.connected_by, v.connected_at, v.updated_by, v.updated_at, coalesce(cu.name, '')::text AS connected_by_name, coalesce(lu.name, '')::text AS last_used_by_name,
       coalesce(uu.name, '')::text AS updated_by_name
FROM verification_services v
LEFT JOIN users cu ON cu.id = v.connected_by
LEFT JOIN users lu ON lu.id = v.last_used_by
LEFT JOIN users uu ON uu.id = v.updated_by
WHERE v.workspace_id = $1
ORDER BY v.connected_at, v.id
`

type VerifServiceListRow struct {
	VerificationService VerificationService `json:"verificationService"`
	ConnectedByName     string              `json:"connectedByName"`
	LastUsedByName      string              `json:"lastUsedByName"`
	UpdatedByName       string              `json:"updatedByName"`
}

// Address verification services (internal/verification): connections,
// jobs and their addresses, each contact's latest result, real-time checks
// on signup forms.
func (q *Queries) VerifServiceList(ctx context.Context, workspaceID uuid.UUID) ([]VerifServiceListRow, error) {
	rows, err := q.db.Query(ctx, verifServiceList, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []VerifServiceListRow{}
	for rows.Next() {
		var i VerifServiceListRow
		if err := rows.Scan(
			&i.VerificationService.ID,
			&i.VerificationService.WorkspaceID,
			&i.VerificationService.Service,
			&i.VerificationService.Region,
			&i.VerificationService.CredentialsEnc,
			&i.VerificationService.PriceMicros,
			&i.VerificationService.DefaultBulk,
			&i.VerificationService.DefaultForms,
			&i.VerificationService.Balance,
			&i.VerificationService.BalanceAt,
			&i.VerificationService.LastUsedAt,
			&i.VerificationService.LastUsedBy,
			&i.VerificationService.LastUsedWhat,
			&i.VerificationService.LastError,
			&i.VerificationService.LastErrorAt,
			&i.VerificationService.LastErrorSince,
			&i.VerificationService.LastSuccessAt,
			&i.VerificationService.LastSuccessWhat,
			&i.VerificationService.TestedAt,
			&i.VerificationService.TestOk,
			&i.VerificationService.LowNotifiedAt,
			&i.VerificationService.ConnectedBy,
			&i.VerificationService.ConnectedAt,
			&i.VerificationService.UpdatedBy,
			&i.VerificationService.UpdatedAt,
			&i.ConnectedByName,
			&i.LastUsedByName,
			&i.UpdatedByName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

