const verifSetTags = `-- name: VerifSetTags :exec
UPDATE contacts c
SET tags = (SELECT coalesce(array_agg(t ORDER BY t), '{}') FROM (
        SELECT t FROM unnest(c.tags) AS t WHERE t NOT LIKE 'verify:%'
        UNION SELECT x.tag WHERE x.tag <> '') s),
    updated_at = now()
FROM (SELECT unnest($2::uuid[]) AS contact_id, unnest($3::text[]) AS tag) AS x
WHERE c.id = x.contact_id AND c.workspace_id = $1
  AND (x.tag = '' AND EXISTS (SELECT 1 FROM unnest(c.tags) t WHERE t LIKE 'verify:%') OR x.tag <> '' AND NOT (x.tag = ANY(c.tags)))
`

type VerifSetTagsParams struct {
	WorkspaceID uuid.UUID   `json:"workspaceId"`
	ContactIds  []uuid.UUID `json:"contactIds"`
	Tags        []string    `json:"tags"`
}

// Replace a contact's verify:… tags with the latest result's (none for valid).
func (q *Queries) VerifSetTags(ctx context.Context, arg VerifSetTagsParams) error {
	_, err := q.db.Exec(ctx, verifSetTags, arg.WorkspaceID, arg.ContactIds, arg.Tags)
	return err
}

const verifSuppressContacts = `-- name: VerifSuppressContacts :many
UPDATE contacts SET status = 'suppressed', updated_at = now()
WHERE workspace_id = $1 AND id = ANY($2::uuid[]) AND erased_at IS NULL AND status = 'active'
RETURNING id
`

type VerifSuppressContactsParams struct {
	WorkspaceID uuid.UUID   `json:"workspaceId"`
	Ids         []uuid.UUID `json:"ids"`
}

// Invalid addresses: the contacts are suppressed for all mail.
func (q *Queries) VerifSuppressContacts(ctx context.Context, arg VerifSuppressContactsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, verifSuppressContacts, arg.WorkspaceID, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

