const verifTierCheckSummary = `-- name: VerifTierCheckSummary :many
SELECT ct.tier, count(*)::bigint AS contacts, count(c.contact_id) FILTER (WHERE c.checked_at >= $1)::bigint AS checked,
       max(c.checked_at)::timestamptz AS last_checked
FROM contacts ct
LEFT JOIN contact_address_checks c ON c.contact_id = ct.id
WHERE ct.workspace_id = $2 AND ct.erased_at IS NULL
GROUP BY ct.tier
`

type VerifTierCheckSummaryParams struct {
	Since       time.Time `json:"since"`
	WorkspaceID uuid.UUID `json:"workspaceId"`
}

type VerifTierCheckSummaryRow struct {
	Tier        string    `json:"tier"`
	Contacts    int64     `json:"contacts"`
	Checked     int64     `json:"checked"`
	LastChecked time.Time `json:"lastChecked"`
}

// Per engagement tier: contacts, and those checked since a time (List
// health's "never checked").
func (q *Queries) VerifTierCheckSummary(ctx context.Context, arg VerifTierCheckSummaryParams) ([]VerifTierCheckSummaryRow, error) {
	rows, err := q.db.Query(ctx, verifTierCheckSummary, arg.Since, arg.WorkspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []VerifTierCheckSummaryRow{}
	for rows.Next() {
		var i VerifTierCheckSummaryRow
		if err := rows.Scan(
			&i.Tier,
			&i.Contacts,
			&i.Checked,
			&i.LastChecked,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
